#include "PresetManager.h"
namespace cymbalforge { bool PresetManager::save(const juce::File& f,const CymbalParameters& p) { auto o=new juce::DynamicObject; o->setProperty("velocity",p.velocity.load()); o->setProperty("position",p.position.load()); o->setProperty("brightness",p.brightness.load()); o->setProperty("decay",p.decay.load()); o->setProperty("complexity",p.complexity.load()); o->setProperty("shimmer",p.shimmer.load()); o->setProperty("noise",p.noise.load()); o->setProperty("reverb",p.reverb.load()); o->setProperty("gain",p.gain.load()); o->setProperty("modes",p.modes.load()); return f.replaceWithText(juce::JSON::toString(juce::var(o),true)); } bool PresetManager::load(const juce::File& f,CymbalParameters& p) { auto v=juce::JSON::parse(f); if(!v.isObject()) return false; auto* o=v.getDynamicObject(); auto setFloat=[o](const char* name, std::atomic<float>& destination) { if(o->hasProperty(name)) destination.store(float(o->getProperty(name))); }; setFloat("velocity",p.velocity); setFloat("position",p.position); setFloat("brightness",p.brightness); setFloat("decay",p.decay); setFloat("complexity",p.complexity); setFloat("shimmer",p.shimmer); setFloat("noise",p.noise); setFloat("reverb",p.reverb); setFloat("gain",p.gain); if(o->hasProperty("modes")) p.modes.store(int(o->getProperty("modes"))); return true; } }
